<?php

declare(strict_types=1);

namespace App\Http\Controllers\Auth;

use Sahil\Auth\AuthManager;
use Sahil\Contracts\Auth\AuthenticatableContract;
use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;
use Sahil\Validation\ValidationResult;
use Sahil\Validation\Validator;

/**
 * Sign-in and sign-out endpoints generated by `php sahil unda:auth`.
 *
 * Credentials are checked by the framework's `AuthManager` (session
 * fixation protection, password rehashing and rate limiting included).
 */
final class LoginController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
        private readonly AuthManager $auth,
    ) {
    }

    public function showLoginForm(): Response
    {
        if ($this->auth->check()) {
            return Response::redirect('/dashboard', 303);
        }

        return $this->page('auth.login');
    }

    public function login(Request $request): Response
    {
        $form = $request->form();
        $email = $this->email($form);

        $result = $this->validator([
            'email' => 'required|email|length:3,190',
            'password' => 'required|string',
        ], [
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
            'password.required' => 'Enter your password.',
        ])->validate([...$form, 'email' => $email]);

        if ($result->fails()) {
            return $this->formPage('auth.login', $result, $form);
        }

        $credentials = [
            'email' => $email,
            'password' => $this->oldString($form, 'password'),
        ];

        if (!$this->auth->attempt($credentials, isset($form['remember']))) {
            // One generic message: never reveal whether the email exists.
            return $this->formPage('auth.login', $result, $form, null, [
                'email' => 'These credentials do not match our records.',
            ]);
        }

        return Response::redirect('/dashboard', 303);
    }

    public function logout(): Response
    {
        $this->auth->logout();

        return Response::redirect('/login', 303);
    }

    /**
     * Authenticated landing page. Reached only through the `Authenticate`
     * middleware on `/dashboard`.
     */
    public function showDashboard(): Response
    {
        $user = $this->auth->user();
        $name = $this->userAttribute($user, 'name', 'there');
        $email = $this->userAttribute($user, 'email', '');

        return $this->page('pages.dashboard', [
            'user' => [
                'name' => $name,
                'email' => $email,
                'initials' => $this->initials($name),
                'role' => 'Member',
            ],
            ...$this->dashboardData(),
        ]);
    }

    /**
     * Demo content for the dashboard. The signed-in account comes from
     * `AuthManager`; these metrics and rows are placeholders to replace with
     * your own queries.
     *
     * @return array<string, mixed>
     */
    private function dashboardData(): array
    {
        return [
            'stats' => [
                ['label' => 'Revenue', 'value' => '$12,480', 'change' => '+12.4%', 'direction' => 'up', 'hint' => 'vs. last month'],
                ['label' => 'New customers', 'value' => '324', 'change' => '+8.1%', 'direction' => 'up', 'hint' => 'vs. last month'],
                ['label' => 'Active projects', 'value' => '18', 'change' => '+2', 'direction' => 'up', 'hint' => 'since last week'],
                ['label' => 'Churn', 'value' => '1.2%', 'change' => '-0.3%', 'direction' => 'down', 'hint' => 'vs. last month'],
            ],
            'activity' => [
                ['initials' => 'GH', 'name' => 'Grace Hopper', 'email' => 'grace@example.com', 'action' => 'Deployed release 1.4.0 to production', 'when' => '12 minutes ago', 'status' => 'Success', 'tone' => 'success'],
                ['initials' => 'AT', 'name' => 'Alan Turing', 'email' => 'alan@example.com', 'action' => 'Created the “Checkout” project', 'when' => '48 minutes ago', 'status' => 'Success', 'tone' => 'success'],
                ['initials' => 'KL', 'name' => 'Katherine Johnson', 'email' => 'katherine@example.com', 'action' => 'Password reset requested', 'when' => '2 hours ago', 'status' => 'Pending', 'tone' => 'pending'],
                ['initials' => 'ML', 'name' => 'Margaret Hamilton', 'email' => 'margaret@example.com', 'action' => 'Invite to the workspace expired', 'when' => 'Yesterday', 'status' => 'Failed', 'tone' => 'failed'],
                ['initials' => 'TK', 'name' => 'Tim Berners-Lee', 'email' => 'tim@example.com', 'action' => 'Updated billing details', 'when' => '2 days ago', 'status' => 'Success', 'tone' => 'success'],
            ],
            'tasks' => [
                ['label' => 'Review the authentication pages', 'done' => true],
                ['label' => 'Connect the login form to AuthManager', 'done' => true],
                ['label' => 'Send the first password-reset mail', 'done' => false],
                ['label' => 'Invite the rest of the team', 'done' => false],
            ],
        ];
    }

    private function userAttribute(?AuthenticatableContract $user, string $key, string $default): string
    {
        if ($user === null) {
            return $default;
        }

        $value = match (true) {
            method_exists($user, 'getAttribute') => $user->getAttribute($key),
            method_exists($user, 'get') => $user->get($key, $default),
            default => $default,
        };

        return is_string($value) ? $value : $default;
    }

    private function initials(string $name): string
    {
        $parts = preg_split('/\s+/', trim($name)) ?: [];
        $initials = '';

        foreach (array_slice($parts, 0, 2) as $part) {
            $initials .= mb_strtoupper(mb_substr($part, 0, 1));
        }

        return $initials === '' ? '?' : $initials;
    }

    /**
     * @param array<string, string|array<int, string|\Closure>> $rules
     * @param array<string, string> $messages
     */
    private function validator(array $rules, array $messages): Validator
    {
        return new Validator($rules, $messages);
    }

    /**
     * Render a form page with validation state.
     *
     * @param array<string, string> $form
     * @param array<string, string> $errors
     */
    private function formPage(
        string $view,
        ?ValidationResult $result = null,
        array $form = [],
        ?string $status = null,
        array $errors = [],
    ): Response {
        $messages = [];

        foreach ($result?->errors() ?? [] as $field => $list) {
            $messages[$field] = $list[0] ?? '';
        }

        return $this->page($view, [
            'errors' => [...$messages, ...$errors],
            'old' => [
                'email' => $this->oldString($form, 'email'),
                'remember' => isset($form['remember']),
            ],
            'status' => $status,
        ]);
    }

    /**
     * @param array<string, mixed> $form
     */
    private function oldString(array $form, string $key): string
    {
        $value = $form[$key] ?? '';

        return is_string($value) ? $value : '';
    }

    /**
     * @param array<string, mixed> $form
     */
    private function email(array $form): string
    {
        return strtolower(trim($this->oldString($form, 'email')));
    }

    /**
     * @param array<string, mixed> $data
     */
    private function page(string $view, array $data = []): Response
    {
        return Response::html($this->views->render($view, [
            'app_name' => (string) $this->application->config()->get('app.name', 'SahilPHP'),
            'year' => gmdate('Y'),
            'csrf_token' => csrf_token(),
            ...$data,
        ]));
    }
}
